      smartReply = "\u0644\u0625\u0637\u0644\u0627\u0644\u0629 \u064A\u0648\u0645\u064A\u0629 \u0639\u0645\u0644\u064A\u0629 \u062A\u062C\u0645\u0639 \u0628\u064A\u0646 \u0627\u0644\u062D\u0634\u0645\u0629 \u0627\u0644\u062A\u0627\u0645\u0629 \u0648\u0627\u0644\u0631\u0627\u062D\u0629 \u0648\u0627\u0644\u0623\u0646\u0627\u0642\u0629 \u0627\u0644\u0639\u0627\u0644\u064A\u0629:\n\u{1F451} \u0623\u0646\u0635\u062D\u0643\u0650 \u0628\u0640 \xAB\u0639\u0628\u0627\u064A\u0629 \u0627\u0644\u0643\u0631\u064A\u0628 \u0627\u0644\u0633\u0639\u0648\u062F\u064A \u0627\u0644\u0641\u0627\u062E\u0631\xBB \u0628\u0642\u0635\u0629 \u0646\u0635 \u0643\u0644\u0648\u0634 \u0645\u0631\u064A\u062D\u0629 \u0644\u0627 \u062A\u062A\u062C\u0639\u062F \u0625\u0637\u0644\u0627\u0642\u0627\u064B \u0645\u0639 \u0627\u0644\u062D\u0631\u0643\u0629.\n\u{1F9E3} \u0627\u0644\u0637\u0631\u062D\u0629: \u0637\u0631\u062D\u0629 \u0642\u0637\u0646 \u0644\u064A\u0632\u0631 \u0628\u0627\u0631\u062F\u0629 \u0623\u0648 \u0643\u0631\u064A\u0628 \u0623\u0633\u0648\u062F \u0641\u0627\u062E\u0631 \u0645\u0627\u0646\u0639 \u0644\u0644\u0627\u0646\u0632\u0644\u0627\u0642.\n\u{1F45F} \u0627\u0644\u062A\u0646\u0633\u064A\u0642: \u062D\u0630\u0627\u0621 \u0633\u0646\u064A\u0643\u0631\u0632 \u062C\u0644\u062F\u064A \u0623\u0628\u064A\u0636 \u0641\u0627\u062E\u0631 \u0623\u0648 \u0641\u0644\u0627\u062A \u0623\u0646\u064A\u0642 \u0628\u0644\u0648\u0646 \u0646\u064A\u0648\u062F \u0645\u0639 \u062D\u0642\u064A\u0628\u0629 \u062A\u0648\u062A \u062C\u0644\u062F\u064A\u0629 \u0639\u0645\u0644\u064A\u0629 \u2726";
