      smartReply = "\u0623\u0633\u0639\u0627\u0631 \u0639\u0628\u0627\u064A\u0627\u062A\u0646\u0627 \u0627\u0644\u0641\u0627\u062E\u0631\u0629 \u062A\u0628\u062F\u0623 \u0645\u0646 45 JOD \u0648\u062A\u0635\u0644 \u0625\u0644\u0649 150 JOD \u0644\u0644\u0642\u0637\u0639 \u0627\u0644\u0645\u0644\u0643\u064A\u0629 \u0627\u0644\u0645\u0637\u0631\u0632\u0629 \u064A\u062F\u0648\u064A\u0627\u064B \u2726\n\u{1F381} \u0647\u062F\u064A\u0629 \u062E\u0627\u0635\u0629 \u0644\u0643\u0650: \u0627\u0633\u062A\u062E\u062F\u0645\u064A \u0643\u0648\u062F \u0627\u0644\u062E\u0635\u0645 \u0627\u0644\u062D\u0635\u0631\u064A (BEESAN2026) \u0639\u0646\u062F \u0625\u062A\u0645\u0627\u0645 \u0627\u0644\u0634\u0631\u0627\u0621 \u0644\u0644\u062D\u0635\u0648\u0644 \u0639\u0644\u0649 \u062E\u0635\u0645 \u062E\u0627\u0635 \u0639\u0644\u0649 \u0637\u0644\u0628\u0643\u0650!";
