      smartReply = "\u064A\u0633\u0639\u062F\u0646\u064A \u0645\u0633\u0627\u0639\u062F\u062A\u0643\u0650 \u0641\u064A \u0627\u062E\u062A\u064A\u0627\u0631 \u0627\u0644\u0645\u0642\u0627\u0633 \u0627\u0644\u0623\u0646\u0633\u0628 \u0644\u0637\u0648\u0644\u0643\u0650:\n\u2022 \u0637\u0648\u0644 150-154 \u0633\u0645: \u0627\u0644\u0645\u0642\u0627\u0633 \u0627\u0644\u0623\u0646\u0633\u0628 \u0647\u0648 (50)\n\u2022 \u0637\u0648\u0644 155-159 \u0633\u0645: \u0627\u0644\u0645\u0642\u0627\u0633 \u0627\u0644\u0623\u0646\u0633\u0628 \u0647\u0648 (52)\n\u2022 \u0637\u0648\u0644 160-164 \u0633\u0645: \u0627\u0644\u0645\u0642\u0627\u0633 \u0627\u0644\u0623\u0646\u0633\u0628 \u0647\u0648 (54)\n\u2022 \u0637\u0648\u0644 165-169 \u0633\u0645: \u0627\u0644\u0645\u0642\u0627\u0633 \u0627\u0644\u0623\u0646\u0633\u0628 \u0647\u0648 (56)\n\u2022 \u0637\u0648\u0644 170-174 \u0633\u0645: \u0627\u0644\u0645\u0642\u0627\u0633 \u0627\u0644\u0623\u0646\u0633\u0628 \u0647\u0648 (58)\n\u2022 \u0637\u0648\u0644 175 \u0633\u0645 \u0641\u0645\u0627 \u0641\u0648\u0642: \u0627\u0644\u0645\u0642\u0627\u0633 \u0627\u0644\u0623\u0646\u0633\u0628 \u0647\u0648 (60)\n\n\u2726 \u0625\u0630\u0627 \u0643\u0646\u062A\u0650 \u062A\u0631\u062A\u062F\u064A\u0646 \u0643\u0639\u0628\u0627\u064B \u0639\u0627\u0644\u064A\u0627\u064B\u060C \u064A\u064F\u0641\u0636\u0644 \u0627\u062E\u062A\u064A\u0627\u0631 \u0645\u0642\u0627\u0633 \u0623\u0643\u0628\u0631 \u0628\u0646\u0645\u0631\u0629 \u0648\u0627\u062D\u062F\u0629 \u0644\u062A\u063A\u0637\u064A\u0629 \u0627\u0644\u0643\u0639\u0628 \u0628\u0623\u0646\u0627\u0642\u0629.";
