      smartReply = "\u0646\u0648\u0641\u0631 \u062E\u062F\u0645\u0629 \u0627\u0644\u0634\u062D\u0646 \u0627\u0644\u0633\u0631\u064A\u0639 \u0644\u0628\u0627\u0628 \u0628\u064A\u062A\u0643\u0650:\n\u{1F69A} \u062F\u0627\u062E\u0644 \u0627\u0644\u0623\u0631\u062F\u0646: \u062A\u0648\u0635\u064A\u0644 \u0633\u0631\u064A\u0639 \u0644\u062C\u0645\u064A\u0639 \u0627\u0644\u0645\u062D\u0627\u0641\u0638\u0627\u062A \u062E\u0644\u0627\u0644 24 - 48 \u0633\u0627\u0639\u0629 \u0641\u0642\u0637.\n\u2708\uFE0F \u0627\u0644\u062A\u0648\u0635\u064A\u0644 \u0627\u0644\u062F\u0648\u0644\u064A (\u0627\u0644\u0633\u0639\u0648\u062F\u064A\u0629\u060C \u062F\u0648\u0644 \u0627\u0644\u062E\u0644\u064A\u062C\u060C \u0623\u0648\u0631\u0648\u0628\u0627\u060C \u0648\u0623\u0645\u0631\u064A\u0643\u0627): \u062E\u0644\u0627\u0644 5 - 8 \u0623\u064A\u0627\u0645 \u0639\u0645\u0644 \u0639\u0628\u0631 \u0634\u0631\u0643\u0627\u062A \u0627\u0644\u0634\u062D\u0646 \u0627\u0644\u0633\u0631\u064A\u0639 \u0645\u0639 \u0631\u0642\u0645 \u062A\u062A\u0628\u0639 \u0645\u0628\u0627\u0634\u0631 \u2726";
