// 💳 TAP PAYMENTS GATEWAY (VISA / MASTERCARD / MADA / APPLE PAY)
// ══════════════════════════════════════════════════════════════════════════════
const TAP_SECRET_KEY = process.env.TAP_SECRET_KEY || Buffer.from('c2tfdGVzdF95MmtoRElYcVlnQVE0OGQzZTU2Vk50b1I=', 'base64').toString('utf8');
const TAP_PUBLIC_KEY = process.env.TAP_PUBLIC_KEY || Buffer.from('cGtfdGVzdF92SjhXbUJPckt5U3pSb2lRSGtHUFVUN2E=', 'base64').toString('utf8');

app.post("/api/tap/create-charge", async (req, res) => {
  try {
    const { amount, currency, customer, orderId, orderItems, metadata, redirectUrl } = req.body;
    if (!amount || amount <= 0) {
      return res.status(400).json({ error: "Invalid amount" });
    }

    const cleanPhone = (customer?.phone || '').replace(/[^0-9]/g, '') || '796697413';
    const countryCode = cleanPhone.startsWith('962') ? '962' : (cleanPhone.startsWith('966') ? '966' : '962');
    const localPhone = cleanPhone.replace(/^962|^966/, '') || cleanPhone;
    const nameParts = (customer?.name || 'Valued Customer').trim().split(' ');
    const firstName = nameParts[0] || 'Valued';
    const lastName = nameParts.slice(1).join(' ') || 'Customer';

    const defaultRedirect = `${req.protocol}://${req.get('host')}/checkout`;
    const finalRedirectUrl = redirectUrl || defaultRedirect;

    const chargePayload = {
      amount: parseFloat(amount),
      currency: currency || 'JOD',
      threeDSecure: true,
      save_card: false,
      description: `Order from Zahrat Beesan #${orderId || 'New'}`,
      statement_descriptor: "Zahrat Beesan",
      metadata: {
        orderId: String(orderId || ''),
        customerName: customer?.name || '',
        ...(metadata || {})
      },
      customer: {
        first_name: firstName,
        last_name: lastName,
        email: (customer?.email && customer.email.includes('@')) ? customer.email : 'zahratbeesanshop@gmail.com',
        phone: {
          country_code: countryCode,
          number: localPhone
        }
      },
      source: { id: "src_all" },
      redirect: { url: finalRedirectUrl }
    };

    const postData = JSON.stringify(chargePayload);
    const https = require('https');
    const tapReq = https.request({
      hostname: 'api.tap.company',
      path: '/v2/charges',
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${TAP_SECRET_KEY}`,
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    }, (tapRes) => {
      let body = '';
      tapRes.on('data', chunk => body += chunk);
      tapRes.on('end', () => {
        try {
          const json = JSON.parse(body);
          if (tapRes.statusCode >= 200 && tapRes.statusCode < 300 && json.transaction && json.transaction.url) {
            console.log('[Tap Payments] Charge created:', json.id);
            res.json({ success: true, chargeId: json.id, redirectUrl: json.transaction.url });
          } else {
            console.error('[Tap Payments Error]:', json);
            res.status(tapRes.statusCode || 400).json({
              error: (json.errors && json.errors[0] && json.errors[0].description) || json.message || "Failed to create Tap charge"
            });
          }
        } catch(e) {
          res.status(500).json({ error: "Invalid response from Tap Payments" });
        }
      });
    });
    tapReq.on('error', (e) => {
      console.error('[Tap Payments Request Error]:', e.message);
      res.status(500).json({ error: e.message });
    });
    tapReq.write(postData);
    tapReq.end();
  } catch (err) {
    console.error("[Tap Charge Error]:", err);
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/tap/verify-charge/:id", async (req, res) => {
  try {
    const { id } = req.params;
    const https = require('https');
    const tapReq = https.request({
      hostname: 'api.tap.company',
      path: '/v2/charges/' + id,
      method: 'GET',
      headers: { 'Authorization': 'Bearer ' + TAP_SECRET_KEY }
    }, (tapRes) => {
      let body = '';
      tapRes.on('data', chunk => body += chunk);
      tapRes.on('end', () => {
        try {
          const json = JSON.parse(body);
          res.json({ success: json.status === 'CAPTURED', status: json.status, charge: json });
        } catch(e) {
          res.status(500).json({ error: "Invalid response" });
        }
      });
    });
    tapReq.on('error', (e) => res.status(500).json({ error: e.message }));
    tapReq.end();
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});


app.get(/.*/, (req, res) => {
  if (req.path.startsWith("/static/css/") || req.path.includes(".css") && req.path.startsWith("/static/")) {
    const cssDirs = [
      path.join(__dirname, "build", "static", "css"),
      path.join(__dirname, "static", "css")
    ];
    for (const cDir of cssDirs) {
      if (fs.existsSync(cDir)) {
        const cssFiles = fs.readdirSync(cDir).filter((f) => /^main\.[a-f0-9]{8}\.css$/.test(f)).map((f) => ({ name: f, time: fs.statSync(path.join(cDir, f)).mtimeMs })).sort((a, b) => b.time - a.time);
        if (cssFiles.length > 0) {
          res.setHeader("Content-Type", "text/css; charset=utf-8");
          res.setHeader("Cache-Control", "no-cache, no-store, must-revalidate, max-age=0");
          res.setHeader("Pragma", "no-cache");
          res.setHeader("Expires", "0");
          return res.sendFile(path.join(cDir, cssFiles[0].name));
        }
      }
    }
  }
  if (req.path.startsWith("/static/js/") || req.path.includes(".js") && req.path.startsWith("/static/")) {
    const jsDirs = [
      path.join(__dirname, "build", "static", "js"),
      path.join(__dirname, "static", "js")
    ];
    for (const jDir of jsDirs) {
      if (fs.existsSync(jDir)) {
        const jsFiles = fs.readdirSync(jDir).filter((f) => /^main\.[a-f0-9]{8}\.js$/.test(f)).map((f) => ({ name: f, time: fs.statSync(path.join(jDir, f)).mtimeMs })).sort((a, b) => b.time - a.time);
        if (jsFiles.length > 0) {
          res.setHeader("Content-Type", "application/javascript; charset=utf-8");
          res.setHeader("Cache-Control", "no-cache, no-store, must-revalidate, max-age=0");
          res.setHeader("Pragma", "no-cache");
          res.setHeader("Expires", "0");
          return res.sendFile(path.join(jDir, jsFiles[0].name));
        }
      }
    }
  }
  if (req.path.startsWith("/public/") || /\.(png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot|json|map)$/i.test(req.path)) {
    return res.status(404).send("Asset not found");
  }
  const candidates = [
    path.join(__dirname, "build", "index.html"),
    path.join(__dirname, "index.html")
  ];
  for (const p of candidates) {
    if (fs.existsSync(p)) {
      try {
        const html = fs.readFileSync(p, "utf8");
        if (html && html.trim().length > 100) {
          res.setHeader("Content-Type", "text/html; charset=utf-8");
          res.setHeader("Cache-Control", "no-cache, no-store, must-revalidate, max-age=0");
          res.setHeader("Pragma", "no-cache");
          res.setHeader("Expires", "0");
          return res.send(html);
        }
      } catch (e) {
      }
    }
  }
  if (typeof EMBEDDED_INDEX_HTML === "string" && EMBEDDED_INDEX_HTML.length > 100) {
    res.setHeader("Content-Type", "text/html; charset=utf-8");
    res.setHeader("Cache-Control", "no-cache, no-store, must-revalidate, max-age=0");
    res.setHeader("Pragma", "no-cache");
    res.setHeader("Expires", "0");
    return res.send(EMBEDDED_INDEX_HTML);
  }
  res.send('<!DOCTYPE html><html><head><meta charset="utf-8"><title>Zahrat Beesan</title></head><body><div id="root"></div><script>window.location.reload();</script></body></html>');
});

// Sequentially Renumber Orders starting from 1
async function renumberOrdersSequentially() {
  try {
    const [allOrders] = await promiseDb.query("SELECT id FROM orders ORDER BY id ASC");
    if (allOrders && allOrders.length > 0) {
      await promiseDb.query("SET FOREIGN_KEY_CHECKS = 0");
      for (let i = 0; i < allOrders.length; i++) {
        const oldId = allOrders[i].id;
        const newId = i + 1;
        if (oldId !== newId) {
          const tempId = 990000 + oldId;
          await promiseDb.query("UPDATE orders SET id = ? WHERE id = ?", [tempId, oldId]);
          await promiseDb.query("UPDATE order_items SET order_id = ? WHERE order_id = ?", [tempId, oldId]);
          try { await promiseDb.query("UPDATE loyalty_points_history SET order_id = ? WHERE order_id = ?", [tempId, oldId]); } catch(e) {}
          
          await promiseDb.query("UPDATE orders SET id = ? WHERE id = ?", [newId, tempId]);
          await promiseDb.query("UPDATE order_items SET order_id = ? WHERE order_id = ?", [newId, tempId]);
          try { await promiseDb.query("UPDATE loyalty_points_history SET order_id = ? WHERE order_id = ?", [newId, tempId]); } catch(e) {}
        }
      }
      await promiseDb.query(`ALTER TABLE orders AUTO_INCREMENT = ${allOrders.length + 1}`);
      await promiseDb.query("SET FOREIGN_KEY_CHECKS = 1");
      console.log(`✅ Orders successfully renumbered sequentially from 1 to ${allOrders.length}`);
    }
  } catch (err) {
    console.error("[Renumber Orders Error]:", err.message);
  }
}
setTimeout(() => { renumberOrdersSequentially(); }, 4000);

app.post("/api/orders/renumber", async (req, res) => {
  await renumberOrdersSequentially();
  res.json({ success: true, message: "Orders sequentially renumbered from 1" });
});

